/*
 * A042727  Denominators of continued fraction convergents to sqrt(893).
 * https://oeis.org/A042727
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) = 12182869998*a(n-22) - a(n-44) for n > 43. Initial values
 *            (first few terms): a(0) = 1 a(1) = 1 a(2) = 8 a(3) = 9 a(4) = 17
 *            ... All remaining terms up to a(43) are generated by the
 *            continued fraction algorithm for sqrt(893). The function returns
 *            a(n) for any n ≥ 0 and can be called in any order
 * Range:     u8 n <= 5, u16 n <= 13, u32 n <= 21, u64 n <= 43, u128 n <= 86,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

static seq_t *cache = NULL;
static size_t cache_cap = 0;
static size_t cache_len = 0;
static int initialized = 0;

static void ensure_cache_size(size_t needed)
{
    if (needed <= cache_cap)
        return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 64;
    while (new_cap <= needed)
        new_cap <<= 1;
    seq_t *new_cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!new_cache) abort(); /* unavoidable in this context */
    cache = new_cache;
    cache_cap = new_cap;
}

static void compute_first_44(void)
{
    const idx_t D = 893;
    const idx_t a0 = 29;          /* floor(sqrt(893)) */
    idx_t m = 0;
    idx_t d = 1;
    idx_t a = a0;
    seq_t q_prev2 = 1;           /* q_-2 */
    seq_t q_prev1 = 0;           /* q_-1 */
    seq_t p_prev2 = 0;
    seq_t p_prev1 = 1;

    for (idx_t k = 0; k <= 43; ++k) {
        seq_t p = a * p_prev1 + p_prev2;
        seq_t q = a * q_prev1 + q_prev2;
        cache[k] = q;

        /* shift for next step */
        p_prev2 = p_prev1; p_prev1 = p;
        q_prev2 = q_prev1; q_prev1 = q;

        /* next continued‑fraction coefficients */
        idx_t m_next = d * a - m;
        idx_t d_next = (D - m_next * m_next) / d;
        a = (a0 + m_next) / d_next;
        m = m_next;
        d = d_next;
    }
    cache_len = 44;
}

/* Main sequence function */
seq_t a(idx_t n)
{
    if (!initialized) {
        ensure_cache_size(44);
        compute_first_44();
        initialized = 1;
    }

    if (n < cache_len)
        return cache[n];

    /* compute values up to index n using recurrence */
    ensure_cache_size(n + 1);
    for (idx_t i = (idx_t)cache_len; i <= n; ++i) {
        seq_t term1 = (seq_t)12182869998 * cache[i - 22];
        seq_t term2 = cache[i - 44];
        cache[i] = term1 - term2;
    }
    cache_len = n + 1;
    return cache[n];
}
